首先自己PS一张图片，大小自定。图片不要太大，会影响加载速度，比如我的是780x120的，并命名为pl.png(后缀名自己可以自定义，前提在css里改好)。
上传到当前博客模板的images文件夹下，修改模板的main.css或是style.css文件内关于textarea对应的代码，如我的模板为例找到以下代码:
input,textarea,button&#123;outline:0;font-size:12px;font-family:&quot;Microsoft YaHei&quot;,&quot;微软雅黑&quot;,&quot;Trebuchet MS&quot;,Arial,Verdana,Tahoma,sans-serif;&#125;
直接在sans-serif;后增加
background: #fff url(images/pl.png) no-repeat center;
完整是这样子滴。
input,textarea,button&#123;outline:0;font-size:12px;font-family:&quot;Microsoft YaHei&quot;,&quot;微软雅黑&quot;,&quot;Trebuchet MS&quot;,Arial,Verdana,Tahoma,sans-serif;background: #fff url(images/pl.png) no-repeat center; &#125;

将下面代码插入在module.php文件内：
代码一:
&lt;?phpfunction maple\_cc()&#123;       session\_start();$timestampcc = time();$cc\_nowtime = $timestampcc;if(isset($\_SESSION\[&#x27;cc\_lasttime&#x27;\]))&#123;$cc\_lasttime = $\_SESSION\[&#x27;cc\_lasttime&#x27;\];$cc\_times = $\_SESSION\[&#x27;cc\_times&#x27;\]+1;$\_SESSION\[&#x27;cc\_times&#x27;\] = $cc\_times;&#125;else&#123;$cc\_lasttime = $cc\_nowtime;$cc\_times = 1;$\_SESSION\[&#x27;cc\_times&#x27;\] = $cc\_times;$\_SESSION\[&#x27;cc\_lasttime&#x27;\] = $cc\_lasttime;&#125; if(($cc\_nowtime-$cc\_lasttime)&lt;60)&#123;if($cc\_times&gt;=3)&#123;header(sprintf(&#x27;Location:%s&#x27;, &#x27;http://127.0.0.1&#x27;));exit;&#125;//60秒内刷新3次以上可能为cc攻击&#125;else&#123;$cc\_times = 0;$\_SESSION\[&#x27;cc\_lasttime&#x27;\] = $cc\_nowtime;$\_SESSION\[&#x27;cc\_times&#x27;\] = $cc\_times;&#125;&#125;?&gt;
代码二:
&lt;?phpfunction maple\_cc()&#123;        //代理IP直接退出        empty($\_SERVER\[&#x27;HTTP\_VIA&#x27;\]) or exit(&#x27;Access Denied&#x27;);        //防止快速刷新        session\_start();        $seconds = &#x27;60&#x27;; //时间段\[秒\]        $refresh = &#x27;3&#x27;; //刷新次数        //设置监控变量        $cur\_time = time();        if(isset($\_SESSION\[&#x27;last\_time&#x27;\]))&#123;                $\_SESSION\[&#x27;refresh\_times&#x27;\] += 1;        &#125;else&#123;                $\_SESSION\[&#x27;refresh\_times&#x27;\] = 1;                $\_SESSION\[&#x27;last\_time&#x27;\] = $cur\_time;        &#125;        //处理监控结果        if($cur\_time - $\_SESSION\[&#x27;last\_time&#x27;\] &lt; $seconds)&#123;                if($\_SESSION\[&#x27;refresh\_times&#x27;\] &gt;= $refresh)&#123;                        //跳转至攻击者服务器地址                        header(sprintf(&#x27;Location:%s&#x27;, &#x27;http://127.0.0.1&#x27;));                        exit(&#x27;Access Denied&#x27;);                &#125;        &#125;else&#123;                $\_SESSION\[&#x27;refresh\_times&#x27;\] = 0;                $\_SESSION\[&#x27;last\_time&#x27;\] = $cur\_time;        &#125;&#125;?&gt;
然后在head.php文件的require\_once View::getView(&#39;module&#39;);后面插入echo maple\_cc();

方法很简单只需两步即可完成，在核心文件module.php加入代码和在文章内页echo_log.php调用即可。
首先在module.php内加入以下代码：
&lt;?php// 判断内容页是否百度收录,并且以博主和或者理员身份访问博客文章时自动向百度提交未收录的文章function baidu($url)&#123; $url=&#x27;http://www.baidu.com/s?wd=&#x27;.$url; $curl=curl\_init(); curl\_setopt($curl,CURLOPT\_URL,$url); curl\_setopt($curl,CURLOPT\_RETURNTRANSFER,1); $rs=curl\_exec($curl); curl\_close($curl); if(!strpos($rs,&#x27;没有找到&#x27;))&#123;     return 1;   &#125; else&#123;     return 0;  &#125;        &#125;  function checkbaidu($id)&#123;  $url=Url::log($id);  if(baidu($url)==1)&#123;   echo &quot;&lt;a style=\\&quot;color:#1EA83A;\\&quot; rel=\\&quot;external nofollow\\&quot; title=\\&quot;点击查看！\\&quot; target=\\&quot;\_blank\\&quot; href=\\&quot;http://www.baidu.com/s?wd=$url\\&quot;&gt;\[百度已收录\]&lt;/a&gt;&quot;;  &#125; else &#123;   if (ROLE == &#x27;admin&#x27;  ROLE == &#x27;writer&#x27;) &#123;    $urls = array($url,); $api = &#x27;http://data.zz.baidu.com/urls?site=https://blog.aneu.cn&amp;token=U1WtVQnKHqd6nTDf&#x27;; $ch = curl\_init(); $options =  array(     CURLOPT\_URL =&gt; $api,     CURLOPT\_POST =&gt; true,     CURLOPT\_RETURNTRANSFER =&gt; true,     CURLOPT\_POSTFIELDS =&gt; implode(&quot;\\n&quot;, $urls),     CURLOPT\_HTTPHEADER =&gt; array(&#x27;Content-Type: text/plain&#x27;),); curl\_setopt\_array($ch, $options); $result = curl\_exec($ch); echo &#x27;&#x27;;   &#125;     echo &quot;&lt;a style=\\&quot;color:red;\\&quot; rel=\\&quot;external nofollow\\&quot; title=\\&quot;点击提交收录！\\&quot; target=\\&quot;\_blank\\&quot; href=\\&quot;http://zhanzhang.baidu.com/sitesubmit/index?sitename=$url\\&quot;&gt;\[百度未收录\]&lt;/a&gt;&quot;;  &#125; &#125;?&gt;&lt;?php//判断内容页是否360收录function haoso($url)&#123;$url=&#x27;https://www.so.com/s?a=index&amp;q=&#x27;.$url;$curl=curl\_init();curl\_setopt($curl,CURLOPT\_URL,$url);curl\_setopt($curl,CURLOPT\_RETURNTRANSFER,1);$rs=curl\_exec($curl);curl\_close($curl);if(!strpos($rs,&#x27;找不到&#x27;))&#123;return 1;&#125;else&#123;return 0;&#125;&#125;function logurlhaoso($id)&#123;$url=Url::log($id);if(haoso($url)==1)&#123;echo &quot;&lt;a style=\\&quot;color:#1EA83A;\\&quot; rel=\\&quot;external nofollow\\&quot; title=\\&quot;点击查看！\\&quot; target=\\&quot;\_blank\\&quot; href=\\&quot;https://www.so.com/s?a=index&amp;q=$url\\&quot;&gt;\[360已收录\]&lt;/a&gt;&quot;;&#125;else&#123;echo &quot;&lt;a style=\\&quot;color:red;\\&quot; rel=\\&quot;external nofollow\\&quot; title=\\&quot;点击提交收录！\\&quot; target=\\&quot;\_blank\\&quot; href=\\&quot;http://info.so.com/site\_submit.html\\&quot;&gt;\[360未收录\]&lt;/a&gt;&quot;;&#125;&#125;?&gt;&lt;?php//判断内容页是否搜狗收录function sogou($url)&#123;$url=&#x27;https://www.sogou.com/sie?query=&#x27;.$url;$curl=curl\_init();curl\_setopt($curl,CURLOPT\_URL,$url);curl\_setopt($curl,CURLOPT\_RETURNTRANSFER,1);$rs=curl\_exec($curl);curl\_close($curl);if(!strpos($rs,&#x27;未收录？&#x27;))&#123;return 1;&#125;else&#123;return 0;&#125;&#125;function logurlsogou($id)&#123;$url=Url::log($id);if(sogou($url)==1)&#123;echo &quot;&lt;a style=\\&quot;color:#1EA83A;\\&quot; rel=\\&quot;external nofollow\\&quot; title=\\&quot;点击查看！\\&quot; target=\\&quot;\_blank\\&quot; href=\\&quot;https://www.sogou.com/sie?query=$url\\&quot;&gt;\[搜狗已收录\]&lt;/a&gt;&quot;;&#125;else&#123;echo &quot;&lt;a style=\\&quot;color:red;\\&quot; rel=\\&quot;external nofollow\\&quot; title=\\&quot;点击提交收录！\\&quot; target=\\&quot;\_blank\\&quot; href=\\&quot;http://fankui.help.sogou.com/index.php/web/web/index/type/1?v=1&amp;urlword=$url\\&quot;&gt;\[搜狗未收录\]&lt;/a&gt;&quot;;&#125;&#125;?&gt;
其次在echo_log.php文件内调用以下代码
百度&lt;?php echo checkbaidu($logid);?&gt;360&lt;?php echo logurlhaoso($logid);?&gt;搜狗&lt;?php echo logurlsogou($logid);?&gt;
最后在说一点更换百度API，例如如下：
$api = &#x27;http://data.zz.baidu.com/urls?site=https://blog.aneu.cn&amp;token=U1WtVQnKHqd6nTDf&#x27;;更换$api = &#x27;自己的百度API&#x27;;

教程开始：
首先将以下代码存放在module文件中：
&lt;?php//判断内容页是否百度收录function baidu($url)&#123;$url=&#x27;http://www.baidu.com/s?wd=&#x27;.$url;$curl=curl\_init();curl\_setopt($curl,CURLOPT\_URL,$url);curl\_setopt($curl,CURLOPT\_RETURNTRANSFER,1);$rs=curl\_exec($curl);curl\_close($curl);if(!strpos($rs,&#x27;没有找到&#x27;))&#123;    return 1;&#125;else&#123;    return 0;&#125;   &#125;function checkbaidu($id)&#123;$url=Url::log($id);if(baidu($url)==1)&#123;echo &quot;百度已收录&quot;;&#125; else &#123;   echo &quot;&lt;a style=\\&quot;color:red;\\&quot; rel=\\&quot;external nofollow\\&quot;    title=\\&quot;点击提交收录！\\&quot; target=\\&quot;\_blank\\&quot;    href=\\&quot;http://zhanzhang.baidu.com/sitesubmit/index?sitename=$url\\&quot;&gt;百度未收录&lt;/a&gt;&quot;;&#125;&#125;?&gt;
然后再将以下代码:
&lt;?php echo checkbaidu($logid); ?&gt;
放入你的echo_log.php文件中的合适位置即可使用

emlog默认防止垃圾评论的方法是保证中文和验证码，保证中文有点死板，验证码又显得复杂，让回复欲望降低不少。小指分享一种简单有效的方法：只需要勾选就可以提交评论。
打开模板的 module.php 文件， 找到合适的位置如：
&lt;input type=&quot;submit&quot; id=&quot;comment\_submit&quot; value=&quot;发表评论&quot; tabindex=&quot;6&quot; /&gt;
在后面添加
&lt;label for=&quot;commentCheck&quot; style=&quot;color: red&quot;&gt;&lt;input type=&quot;checkbox&quot; value=9 id=&quot;commentCheck&quot; name=&quot;commentCheck&quot; required=&quot;required&quot; autocomplete=&quot;on&quot; required title=&quot;发表评论确认框：请勾选我再发表评论！&quot;&gt;请勾选我再发表评论！&lt;/label&gt;
完成，有需要的试试吧～

很早就发现手机页面没有搜索框了，后来才知道因为模板开发的时候作者就没有考虑到手机方面的问题，所以一直都没有搜索功能，博主的模板也是emlog媒体范这个模版自适应的，然后今天给大家出这个搜索框手机端自适应访问时怎么才能显示出来呢？
这个问题想起了我第一次接触自适应代码，那是看到媒体范这个模版自适应到手机版时搜索框就不在了，好奇心的驱使下，找了很多和我一样模板的大佬然后就开始仿。
教程：
把以下的代码复制放到模版文件夹公用的&#x2F;style.css 文件里面（列如）

@media only screen and (max-width: 650px) &#123;.logo&#123;float:none;text-align:center;margin:0 auto&#125;.search-fr&#123;float: none;margin:0 auto;display:block !important;margin:0 auto;padding-top:1px;&#125;&#125;
其中logo和搜索框都做了居中，如果不喜欢居中的只需要把下面这段代码删除就行。
.logo&#123;float:none;text-align:center;margin:0 auto&#125;
原创:杨小杰博客

