转载诗梦博客

由于多说停止服务，所有有部分使用多说的emlog用户想要将在多说导出的json评论数据倒进自己的博客中，使用本脚本可以实现这个功能。详细代码如下，如果你使用的是emlog博客程序，即可以使用这个脚本进行导入。注意，导入后会丢失评论的父子关系。文章的ID是通过 thread_key 参数指定的，如果你没有开启 thread_key 设置，不要使用这个脚本。本脚本会将评论数据添加到指定文章下。且会自动更新对应文章的评论数。

以下为全部代码，将其保存为php文件上传到服务器执行即可。
&lt;?phperror\_reporting(0); header(&quot;Content-type:text/html;charset=utf-8&quot;);date\_default\_timezone\_set(&#x27;Etc/GMT-8&#x27;);?&gt;&lt;form action=&quot;?ok=post&quot; method=&quot;get&quot;&gt;&lt;input type=&quot;hidden&quot; name=&quot;ok&quot; value=&quot;post&quot;&gt;&lt;div style=&quot;margin:30px 0px;height:16px;line-height:16px;&quot;&gt;&amp;nbsp;数据库地址:&lt;input id=&quot;host&quot; name=&quot;host&quot; type=&quot;text&quot;&gt;一般为localhost&lt;/div&gt;&lt;div style=&quot;margin:30px 0px;height:16px;line-height:16px;&quot;&gt;&amp;nbsp;数据库名:&lt;input id=&quot;name&quot; name=&quot;name&quot; type=&quot;text&quot;&gt;填写emlog博客所在的数据库&lt;/div&gt;&lt;div style=&quot;margin:30px 0px;height:16px;line-height:16px;&quot;&gt;&amp;nbsp;数据库账号:&lt;input id=&quot;user&quot; name=&quot;user&quot; type=&quot;text&quot;&gt;&lt;/div&gt;&lt;div style=&quot;margin:30px 0px;height:16px;line-height:16px;&quot;&gt;&amp;nbsp;数据库密码:&lt;input id=&quot;pass&quot; name=&quot;pass&quot; type=&quot;text&quot;&gt;&lt;/div&gt;&lt;div style=&quot;margin:30px 0px;height:16px;line-height:16px;&quot;&gt;&amp;nbsp;数据库前缀:&lt;input id=&quot;prefix&quot; name=&quot;prefix&quot; type=&quot;text&quot;&gt;一定要正确，如 emlog\_&lt;/div&gt;&lt;input style=&quot;border:1px solid #ccc;width:112px;height:30px;line-height:30px;background:#fff;&quot; type=&quot;submit&quot; value=&quot;确定&quot;&gt;确认无误后点击确定即可。&lt;/form&gt;&lt;?phpif($\_GET\[&#x27;ok&#x27;\] == &#x27;post&#x27;)&#123;$host = $\_GET\[&#x27;host&#x27;\] ? $\_GET\[&#x27;host&#x27;\] : &#x27;&#x27;;$name = $\_GET\[&#x27;name&#x27;\] ? $\_GET\[&#x27;name&#x27;\] : &#x27;&#x27;;$user = $\_GET\[&#x27;user&#x27;\] ? $\_GET\[&#x27;user&#x27;\] : &#x27;&#x27;;$pass = $\_GET\[&#x27;pass&#x27;\] ? $\_GET\[&#x27;pass&#x27;\] : &#x27;&#x27;;$prefix = $\_GET\[&#x27;prefix&#x27;\] ? $\_GET\[&#x27;prefix&#x27;\] : &#x27;&#x27;;if($host == &#x27;&#x27; or  $name == &#x27;&#x27; or $user == &#x27;&#x27; or $pass == &#x27;&#x27; or $prefix == &#x27;&#x27;)&#123;echo &#x27;参数不完整，请填写完整参数&lt;br&gt;&#x27;;exit;&#125;else&#123;$con = mysql\_connect($host,$user,$pass); //连接数据库if(!$con)&#123;die(&#x27;不能连接数据库服务器:&#x27;.mysql\_error());&#125;mysql\_select\_db($name,$con);//选择数据库mysql\_query(&quot;set names &#x27;utf8&#x27;&quot;);echo &#x27;连接数据库成功&lt;br&gt;&#x27;;&#125;//判断数据表是否存在$sql=&quot;show tables like &#x27;&quot;.$prefix.&quot;comment&#x27;&quot;;$result = mysql\_query($sql,$con);if(mysql\_num\_rows($result))&#123;echo &#x27;评论数据表找到&lt;br&gt;&#x27;;&#125;else&#123;echo &#x27;&lt;span style=&quot;color:#f00;&quot;&gt;评论数据表不存在，可能是前缀填写错误&lt;/span&gt;&lt;br&gt;&#x27;;exit;&#125;$sql=&quot;show tables like &#x27;&quot;.$prefix.&quot;blog&#x27;&quot;;$result = mysql\_query($sql,$con);if(mysql\_num\_rows($result))&#123;echo &#x27;文章数据表找到&lt;br&gt;&#x27;;&#125;else&#123;echo &#x27;&lt;span style=&quot;color:#f00;&quot;&gt;文章数据表不存在，可能是前缀填写错误&lt;/span&gt;&lt;br&gt;&#x27;;exit;&#125;echo &#x27;开始写入评论数据&lt;br&gt;&#x27;;//唯一需要修改的地方，将在多说导出的json数据全部复制到‘’中间$json = &#x27;&#123;&quot;generator&quot;:&quot;duoshuo&quot;,&quot;version&quot;:&quot;0.1&quot;,&quot;threads&quot;:\[&#123;&quot;site\_id&quot;:1176228,&quot;thread\_id&quot;:12...&#125;&#x27;;$unjson = json\_decode($json,true);$jishu = 0;$number = count($unjson\[&#x27;posts&#x27;\]);while($jishu &lt; $number)&#123;$gid = $unjson\[&#x27;posts&#x27;\]\[$jishu\]\[&#x27;thread\_key&#x27;\] ? $unjson\[&#x27;posts&#x27;\]\[$jishu\]\[&#x27;thread\_key&#x27;\] : -1;$pid = 0;$date = mktime(substr($unjson\[&#x27;posts&#x27;\]\[$jishu\]\[&#x27;created\_at&#x27;\],11,2),substr($unjson\[&#x27;posts&#x27;\]\[$jishu\]\[&#x27;created\_at&#x27;\],14,2),substr($unjson\[&#x27;posts&#x27;\]\[$jishu\]\[&#x27;created\_at&#x27;\],17,2),substr($unjson\[&#x27;posts&#x27;\]\[$jishu\]\[&#x27;created\_at&#x27;\],5,2),substr($unjson\[&#x27;posts&#x27;\]\[$jishu\]\[&#x27;created\_at&#x27;\],8,2),substr($unjson\[&#x27;posts&#x27;\]\[$jishu\]\[&#x27;created\_at&#x27;\],0,4));if($date == &#x27;&#x27;)&#123;$date = time();&#125;$poster = $unjson\[&#x27;posts&#x27;\]\[$jishu\]\[&#x27;author\_name&#x27;\] ? $unjson\[&#x27;posts&#x27;\]\[$jishu\]\[&#x27;author\_name&#x27;\] : &#x27;匿名&#x27;;$comment = $unjson\[&#x27;posts&#x27;\]\[$jishu\]\[&#x27;message&#x27;\] ? $unjson\[&#x27;posts&#x27;\]\[$jishu\]\[&#x27;message&#x27;\] : &#x27;&#x27;;$mail = $unjson\[&#x27;posts&#x27;\]\[$jishu\]\[&#x27;author\_email&#x27;\] ? $unjson\[&#x27;posts&#x27;\]\[$jishu\]\[&#x27;author\_email&#x27;\] : &#x27;&#x27;;$url = $unjson\[&#x27;posts&#x27;\]\[$jishu\]\[&#x27;author\_url&#x27;\] ? $unjson\[&#x27;posts&#x27;\]\[$jishu\]\[&#x27;author\_url&#x27;\] : &#x27;&#x27;;$ip = $unjson\[&#x27;posts&#x27;\]\[$jishu\]\[&#x27;ip&#x27;\] ? $unjson\[&#x27;posts&#x27;\]\[$jishu\]\[&#x27;ip&#x27;\] : &#x27;&#x27;;$hide = &#x27;n&#x27;;$sql=&quot;INSERT INTO &quot;.$prefix.&quot;comment (gid,pid,date,poster ,comment,mail,url,ip,hide) VALUES (&#123;$gid&#125;,&#123;$pid&#125;,&#123;$date&#125;,&#x27;&#123;$poster&#125;&#x27;,&#x27;&#123;$comment&#125;&#x27;,&#x27;&#123;$mail&#125;&#x27;,&#x27;&#123;$url&#125;&#x27;,&#x27;&#123;$ip&#125;&#x27;,&#x27;n&#x27;)&quot;;mysql\_query($sql,$con);//写入评论$sql=&quot;UPDATE &quot;.$prefix.&quot;blog SET comnum=comnum+1 WHERE gid = &#123;$gid&#125;&quot;;mysql\_query($sql,$con);//更新文章评论数//echo $jishu.&#x27; 更新成功&lt;br&gt;&#x27;;$jishu++;&#125;echo $jishu.&#x27;条评论数据已写入数据库，现在你可以关闭本页面了。&lt;br&gt;&#x27;;&#125;

